function visibleAgents(agents){return agents.filter(a=>showStaleAgents||a.pool_status==='busy'||a.pool_status==='available'||a.pool_status==='connected').sort(compareAgents)}
function relativeAge(value,now=Date.now()){if(!value)return'Not observed';const then=new Date(value).getTime();if(!Number.isFinite(then))return'Not observed';const seconds=Math.max(0,Math.floor((now-then)/1000));if(seconds<60)return`${seconds}s ago`;const minutes=Math.floor(seconds/60);if(minutes<60)return`${minutes}m ago`;const hours=Math.floor(minutes/60);if(hours<24)return`${hours}h ago`;return`${Math.floor(hours/24)}d ago`}
