function agentRosterTiming(a,seat){const lease=seat.lease_expires_at||seat.current_ticket_lease_expires_at;if(lease)return`Lease until ${fmt(lease)}`;const seen=seat.last_seen||a.last_seen;return seen?`Last seen ${relativeAge(seen)}`:'Last seen Not observed'}
