function refreshPaused(){const a=document.activeElement,state=document.querySelector('#state');const focused=!!a&&a!==document.body&&a.id!=='filter'&&a.matches('input,textarea,select,[contenteditable="true"]');const dirty=[...document.querySelectorAll('form[data-dirty]')].some(form=>!form.closest('[hidden]'));const paused=focused||dirty;if(state){if(paused){if(!state.dataset.paused){state.dataset.paused='1';state.dataset.prev=state.textContent;state.textContent='Refresh paused while editing · click to resume';state.title='Auto-refresh is paused while a form has focus or unsaved input. Click to resume.';announceState('Auto-refresh paused while you edit')}}else if(state.dataset.paused){delete state.dataset.paused;state.textContent=state.dataset.prev||'';state.title='';announceState('Auto-refresh resumed')}}let pill=document.querySelector('#refresh-paused');if(paused){if(!pill&&document.body){pill=document.createElement('div');pill.id='refresh-paused';pill.setAttribute('role','status');pill.innerHTML='<span>Auto-refresh paused while you edit</span><button type="button" id="refresh-resume">Resume</button>';document.body.appendChild(pill)}}else pill?.remove();return paused}
document.addEventListener('input',e=>{const t=e.target;if(t instanceof Element&&t.id!=='filter'&&t.form)t.form.dataset.dirty='1'},true);document.addEventListener('submit',e=>{if(e.target instanceof HTMLFormElement)delete e.target.dataset.dirty},true);document.addEventListener('reset',e=>{if(e.target instanceof HTMLFormElement)delete e.target.dataset.dirty},true);document.addEventListener('click',e=>{if(e.target.closest?.('#state,#refresh-resume')){document.querySelectorAll('form[data-dirty]').forEach(f=>delete f.dataset.dirty);document.activeElement?.blur?.();refreshPaused()}});
