function pressureBadge(s){const label=s.pressure==='compact'?'COMPACT':s.pressure;return `<span class="status pressure-${esc(s.pressure)}" title="${esc(s.next_action)}">${esc(label)}</span>`}
function renderOverhead(d){const sessions=d.sessions||[],model=d.model_wait||[],cumulative=d.seats||[];document.querySelector('#detail-view').innerHTML=`<a class="back" href="#/">← All centrals</a><div class="top"><div><h2>Session context pressure · ${esc(d.central)}</h2><p class="muted">Model-visible wait cost is separated from bridge-to-Central diagnostics.</p></div></div><section class="card pool"><h3>Model-visible a2a_wait cost</h3>${model.length?`<div class="table-scroll"><table aria-label="Model-visible wait cost"><thead><tr><th>Seat</th><th>Returns this hour</th><th>Context this hour</th><th>24-hour outcomes</th></tr></thead><tbody>${model.map(s=>`<tr><td><b>${esc(s.agent_name)}</b><div class="meta">${esc(s.board_id)}</div></td><td>${esc(s.returns_per_hour)}</td><td>${esc(s.context_bytes_per_hour)} B<div class="meta">≈ ${esc(s.estimated_tokens_per_hour)} tokens</div></td><td>${esc(JSON.stringify(s.outcomes||{}))}<div class="meta">${esc(s.last_24h_returns)} returns · ${esc(s.last_24h_context_bytes)} B</div></td></tr>`).join('')}</tbody></table></div>`:`<p class="empty">No model-visible wait returns yet.</p>`}</section><section class="card pool">${sessions.length?`<div class="table-scroll"><table aria-label="Session context pressure"><thead><tr><th>Seat</th><th>Board</th><th>Est. tokens / poll</th><th>Trend vs median</th><th>Pressure</th></tr></thead><tbody>${sessions.map(s=>`<tr><td><b>${esc(s.agent_name)}</b><div class="meta">sampled ${esc(fmt(s.latest_at))}</div></td><td>${esc(s.board_id)}</td><td>${esc(s.latest_estimated_tokens)}</td><td>${esc(s.trend)} ${s.trend_ratio===null?'—':`${esc(s.trend_ratio)}×`}<div class="meta">24-sample median ≈ ${esc(s.median_estimated_tokens)} tokens · ${esc(s.sample_count)} samples</div></td><td>${pressureBadge(s)}<div class="meta">${esc(s.next_action)}</div></td></tr>`).join('')}</tbody></table></div>`:`<p class="empty">No session pressure samples yet — context pressure is calm (${esc(d.source_status)}).</p>`}</section><details class="card pool" data-state-key="overhead-details:${esc(d.central)}"><summary>Bridge-to-Central diagnostic details</summary>${cumulative.length?`<div class="table-scroll"><table><thead><tr><th>Seat</th><th>Today</th><th>7-day</th><th>Top tools by bytes</th></tr></thead><tbody>${cumulative.map(s=>`<tr><td><b>${esc(s.agent_name)}</b><div class="meta">${esc(s.board_id)}</div></td><td>${esc(s.today_bytes)} B<div class="meta">≈ ${esc(s.today_estimated_tokens)} tokens · ${esc(s.today_calls)} calls</div></td><td>${esc(s.seven_day_bytes)} B<div class="meta">≈ ${esc(s.seven_day_estimated_tokens)} tokens · ${esc(s.seven_day_calls)} calls</div></td><td class="overhead-tools">${s.top_tools.map(t=>`${esc(t.tool)}: ${esc(t.bytes)} B`).join(' · ')||'—'}</td></tr>`).join('')}</tbody></table></div>`:`<p class="empty">No cumulative debug stats.</p>`}</details>`;bindInteractive(document.querySelector('#detail-view'))}
function sortedTickets(items){const rank=s=>['claimed','in_progress','creating_report'].includes(s)?0:['submitted','reviewing','in_review'].includes(s)?1:s==='open'?2:3;return [...items].sort((a,b)=>rank(a.status)-rank(b.status)||(detailSort==='oldest'?String(a.updated_at||'').localeCompare(String(b.updated_at||'')):String(b.updated_at||'').localeCompare(String(a.updated_at||''))))}
function tabs(d,r){return `<nav class="tabs" aria-label="Board views">${[['tickets','Tickets'],['timeline','Timeline'],['changes','Changes'],['flow','Ticket Flow'],['routes','Routes']].map(([v,label])=>`<a class="tab${r.view===v?' active':''}" href="${boardHref(r.central,d.board.board_id,v)}">${esc(label)}</a>`).join('')}</nav>`}
async function copyHandoffValue(button){const value=button.dataset.copyHandoff||'',original=button.textContent;let copied=false;try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);copied=true}}catch(_error){}if(!copied){const input=document.createElement('textarea');input.value=value;input.readOnly=true;input.style.position='fixed';input.style.left='-10000px';document.body.append(input);input.select();try{copied=document.execCommand('copy')}catch(_error){}input.remove()}button.textContent=copied?'Copied':'Copy unavailable';setTimeout(()=>button.textContent=original,1500)}
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-copy-handoff]');if(button)copyHandoffValue(button)})
function handoffView(t,r,d){const h=t.latest_handoff;if(!h)return'';const source=h.source||'Not observed',destination=h.destination||'reviewer unassigned',connected=Boolean(h.source&&h.destination),ticket=h.ticket_id||'Not supplied',summary=h.summary||'Not supplied',steps=(h.next_steps||[]).length?`<ul>${h.next_steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ul>`:'<p class="meta">None recorded</p>',arrow=connected?`<span class="handoff-arrow" role="img" aria-label="Handoff from ${esc(source)} to ${esc(destination)}"><span aria-hidden="true">→</span></span>`:'';return`<article class="handoff-card"><span class="handoff-kicker">Latest explicit handoff</span><div class="handoff-route" data-connected="${connected}"><div class="handoff-endpoint"><span>Source agent</span><strong>${esc(source)}</strong></div>${arrow}<div class="handoff-endpoint"><span>Destination</span><strong>${esc(destination)}</strong></div></div><blockquote>${esc(summary)}</blockquote><div class="handoff-next"><b>Next steps</b>${steps}</div><div class="handoff-meta"><a class="id" href="${ticketHref(r.central,d.board.board_id,ticket)}">${esc(ticket)}</a><span>${esc(h.created_at?fmt(h.created_at):'Not observed')}</span><span class="handoff-memory"><code>${esc(h.memory_id||'Not supplied')}</code>${h.memory_id?`<button type="button" data-copy-handoff="${esc(h.memory_id)}" aria-label="Copy memory ID ${esc(h.memory_id)}">Copy memory ID</button>`:''}</span></div></article>`}
function annotationView(t){const rows=t.annotations||[],omitted=Number(t.annotations_omitted_count||0);if(!rows.length&&!omitted)return'';return`<section class="ticket-annotations"><h3>Annotations · ${esc(t.annotation_count||rows.length)}</h3>${omitted?`<p class="meta">${esc(omitted)} older annotation(s) omitted.</p>`:''}${rows.map(a=>{const by=a.by||{},author=by.agent_name||by.agent_id||by.principal_id||'unknown';return`<article class="finding annotation"><span class="pill annotation-kind">${esc(a.kind||'note')}</span> <span class="id">${esc(a.annotation_id)}</span><p class="ticket-copy">${esc(a.text)}</p><p class="meta">By ${esc(author)} · ${esc(fmt(a.at))}</p></article>`}).join('')}</section>`}
// merge retained rc6 lifecycle rendering below; the combined override follows the main activity rendering.
function ticketViewMainActivityV1LegacyLifecycleV1(d,r){const rows=sortedTickets(d.tickets).filter(t=>matches([t.id,t.title,t.status,t.claimed_by,t.description],filterNeedle));const visible=!r.ticket||rows.some(t=>t.id===r.ticket);return `${visible?'':`<p class="warning">Requested ticket ${esc(r.ticket)} is outside this bounded response or filter.</p>`}<div class="toolbar"><span>${esc(rows.length)} of ${esc(d.ticket_returned)} returned tickets</span><label>Updated <select id="ticket-sort"><option value="newest"${detailSort==='newest'?' selected':''}>newest first</option><option value="oldest"${detailSort==='oldest'?' selected':''}>oldest first</option></select></label></div><section class="card"><div class="table-scroll"><table><thead><tr><th>Ticket</th><th>Title and details</th><th>Status</th><th class="hide-small">Updated</th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr data-ticket-status="${esc(t.status)}" data-active-ticket-row="${['open','claimed','in_progress','creating_report','submitted','reviewing','in_review'].includes(t.status)}"><td><span class="id">${esc(t.id)}</span></td><td><details class="ticket-detail" data-ticket="${esc(t.id)}" data-state-key="${esc(`ticket:${r.central}:${d.board.board_id}:${t.id}`)}"${r.ticket===t.id?' open':''}><summary>${esc(t.title)}</summary><div class="ticket-detail-body">${ticketCoordination(t)}${ticketLifecycle(t)}<p class="ticket-copy">${esc(t.description||'No description')}</p>${t.required_fields.length?`<div class="required">${t.required_fields.map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div>`:''}${t.latest_submission_summary?`<p class="meta ticket-copy">Latest submission: ${esc(t.latest_submission_summary)}</p>`:''}${t.review_label?`<p class="meta">Review: ${esc(t.review_label)}</p>`:''}${annotationView(t)}</div></details></td><td><span class="status">${esc(t.status)}</span><div class="meta">${esc(t.claimed_by||'')}</div></td><td class="meta hide-small">${esc(fmt(t.updated_at))}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No tickets match the filter.</td></tr>'}</tbody></table></div></section>`}
function timelineViewLegacyLifecycleV1(d,r){const bySeq=new Map(d.events.map(e=>[e.seq,e]));const groups=d.timeline.map(day=>({...day,tickets:day.tickets.map(t=>({...t,events:t.event_seqs.map(seq=>bySeq.get(seq)).filter(Boolean).filter(e=>eventMatches(e,t.ticket_id,filterNeedle))})).filter(t=>t.events.length)})).filter(day=>day.tickets.length);return `<p class="muted bounded-note">Showing last ${esc(d.event_returned)} events from a read-only bounded catchup (ack=false).</p><section class="timeline">${groups.length?groups.map(day=>`<details class="card" data-state-key="${esc(`timeline-day:${r.central}:${d.board.board_id}:${day.day}`)}" open><summary><b>${esc(day.day)}</b></summary>${day.tickets.map(t=>`<details class="timeline-ticket" data-state-key="${esc(`timeline-ticket:${r.central}:${d.board.board_id}:${t.ticket_id}`)}"><summary><a class="id" href="${ticketHref(r.central,d.board.board_id,t.ticket_id)}">${esc(t.ticket_id)}</a> · ${esc(t.events.length)} event(s)</summary><div class="table-scroll"><table><tbody>${t.events.map(e=>`<tr><td class="id">${esc(e.seq)}</td><td>${esc(e.kind)}</td><td>${esc(e.status_from||'—')} → ${esc(e.status_to||'—')}</td><td class="meta">${esc(fmt(e.occurred_at))}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}</details>`).join(''):'<p class="empty">No timeline events match the filter.</p>'}</section>`}
// merge retained main activity rendering below.
function detailActivityNotices(d){return`${d.event_resync_required?'<p class="warning ticket-activity-notice">This bounded catchup required a journal resync; earlier events were not observed.</p>':''}${d.event_window_truncated?'<p class="meta ticket-activity-notice">Older events omitted from this bounded view.</p>':''}`}
function eventTypeSummary(e){const kind=e.kind?String(e.kind).replaceAll('_',' '):'Not observed';return e.status_from||e.status_to?`${kind} · ${e.status_from||'Not observed'} → ${e.status_to||'Not observed'}`:kind}
function ticketActivityView(d,r,t){const events=[...(d.events||[])].filter(e=>e.ticket_id===t.id).sort((a,b)=>(Number.isInteger(b.seq)?b.seq:-1)-(Number.isInteger(a.seq)?a.seq:-1)).slice(0,3),allHref=boardHref(r.central,d.board.board_id,'timeline'),heading=`<div class="ticket-activity-heading"><h3>Recent activity</h3><a href="${allHref}">View all</a></div>`,notices=detailActivityNotices(d);if(!events.length)return`<section class="ticket-activity" aria-label="Recent activity for ${esc(t.id)}">${heading}<p class="empty ticket-activity-empty">Not observed — no ticket-scoped journal events are present in this bounded response.</p>${notices}</section>`;return`<section class="ticket-activity" aria-label="Recent activity for ${esc(t.id)}">${heading}<details class="ticket-activity-disclosure"><summary>Show newest ${esc(events.length)} ticket event${events.length===1?'':'s'}</summary><ol class="ticket-activity-list">${events.map(e=>`<li class="ticket-activity-event" data-event-seq="${esc(Number.isInteger(e.seq)?e.seq:'Not observed')}"><span class="id"><span class="sr-only">Sequence </span>${Number.isInteger(e.seq)?`#${esc(e.seq)}`:'Not observed'}</span><span>${esc(eventTypeSummary(e))}</span><span class="ticket-activity-actor">${esc(e.actor||'Not observed')}</span><span class="meta ticket-activity-time">${e.occurred_at?`<time datetime="${esc(e.occurred_at)}">${esc(fmt(e.occurred_at))}</time>`:'Not observed'}</span></li>`).join('')}</ol></details>${notices}</section>`}
function ticketViewMainActivityV1(d,r){const rows=sortedTickets(d.tickets).filter(t=>matches([t.id,t.title,t.status,t.claimed_by,t.description],filterNeedle));const visible=!r.ticket||rows.some(t=>t.id===r.ticket);return `${visible?'':`<p class="warning">Requested ticket ${esc(r.ticket)} is outside this bounded response or filter.</p>`}<div class="toolbar"><span>${esc(rows.length)} of ${esc(d.ticket_returned)} returned tickets</span><label>Updated <select id="ticket-sort"><option value="newest"${detailSort==='newest'?' selected':''}>newest first</option><option value="oldest"${detailSort==='oldest'?' selected':''}>oldest first</option></select></label></div><section class="card"><div class="table-scroll"><table><thead><tr><th>Ticket</th><th>Title and details</th><th>Status</th><th class="hide-small">Updated</th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr><td><span class="id">${esc(t.id)}</span></td><td><details class="ticket-detail" data-ticket="${esc(t.id)}" data-state-key="${esc(`ticket:${r.central}:${d.board.board_id}:${t.id}`)}"${r.ticket===t.id?' open':''}><summary>${esc(t.title)}</summary><div class="ticket-detail-body">${ticketCoordination(t)}${ticketLifecycle(t)}<p class="ticket-copy">${esc(t.description||'No description')}</p>${t.required_fields.length?`<div class="required">${t.required_fields.map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div>`:''}${t.latest_submission_summary?`<p class="meta ticket-copy">Latest submission: ${esc(t.latest_submission_summary)}</p>`:''}${t.review_label?`<p class="meta">Review: ${esc(t.review_label)}</p>`:''}${ticketActivityView(d,r,t)}${handoffView(t,r,d)}${annotationView(t)}</div></details></td><td><span class="status">${esc(t.status)}</span><div class="meta">${esc(t.claimed_by||'')}</div></td><td class="meta hide-small">${esc(fmt(t.updated_at))}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No tickets match the filter.</td></tr>'}</tbody></table></div></section>`}
function timelineView(d,r){const bySeq=new Map(d.events.map(e=>[e.seq,e]));const groups=d.timeline.map(day=>({...day,tickets:day.tickets.map(t=>({...t,events:t.event_seqs.map(seq=>bySeq.get(seq)).filter(Boolean).filter(e=>eventMatches(e,t.ticket_id,filterNeedle))})).filter(t=>t.events.length)})).filter(day=>day.tickets.length);return `<p class="muted bounded-note">Showing last ${esc(d.event_returned)} events from a read-only bounded catchup (ack=false).</p>${detailActivityNotices(d)}<section class="timeline">${groups.length?groups.map(day=>`<details class="card" data-state-key="${esc(`timeline-day:${r.central}:${d.board.board_id}:${day.day}`)}" open><summary><b>${esc(day.day)}</b></summary>${day.tickets.map(t=>`<details class="timeline-ticket" data-state-key="${esc(`timeline-ticket:${r.central}:${d.board.board_id}:${t.ticket_id}`)}"><summary><a class="id" href="${ticketHref(r.central,d.board.board_id,t.ticket_id)}">${esc(t.ticket_id)}</a> · ${esc(t.events.length)} event(s)</summary><div class="table-scroll"><table><tbody>${t.events.map(e=>`<tr><td class="id">${esc(e.seq)}</td><td>${esc(e.kind)}</td><td>${esc(e.status_from||'—')} → ${esc(e.status_to||'—')}</td><td class="meta">${esc(fmt(e.occurred_at))}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}</details>`).join(''):'<p class="empty">No timeline events match the filter.</p>'}</section>`}
// end retained ticket renderers.
function ticketLease(value){if(!value)return{text:'Not supplied',stale:false};const remaining=new Date(value).getTime()-Date.now();if(!Number.isFinite(remaining))return{text:'Not supplied',stale:false};if(remaining<=0)return{text:'lease expired',stale:true};const minutes=Math.max(1,Math.ceil(remaining/60000));return{text:`lease ${minutes}m`,stale:false}}
function ticketCoordination(t){const c=t.coordination||{now:{text:'Not supplied',lease_expected:false},next:'Not supplied',blocked:null},lease=c.now.lease_expected?ticketLease(c.now.lease_expires_at):null,blocked=c.blocked;return `<section class="ticket-coordination" aria-label="Now, next, and blocked"><div class="ticket-coordinate"><span>NOW</span><b>${esc(c.now.text||'Not supplied')}</b>${lease?` <small class="${lease.stale?'warning':'meta'}">${esc(lease.text)}</small>`:''}</div><div class="ticket-coordinate"><span>NEXT</span><b>${esc(c.next||'Not supplied')}</b></div><div class="ticket-coordinate"><span>BLOCKED</span><b>${blocked?`${esc(blocked.kind)} · ${esc(blocked.text)}`:'None recorded'}</b>${blocked?.at?`<small class="meta">${esc(fmt(blocked.at))}</small>`:''}</div></section>`}
function ticketLifecycle(t){const stages=t.lifecycle||[];return `<ol class="ticket-lifecycle" aria-label="Ticket lifecycle">${stages.map(stage=>{const current=stage.state==='current',icon=stage.state==='pending'?'○':'●',evidence=stage.observed?[stage.at?fmt(stage.at):null,stage.actor].filter(Boolean).join(' · ')||'Not observed':'Not observed';return `<li class="ticket-stage ${esc(stage.state)}"><span class="ticket-stage-icon" aria-hidden="true">${icon}</span><div><b>${esc(stage.label)}</b>${current?'<span class="ticket-stage-current">↑ Current</span>':''}<span class="meta">${esc(evidence)}</span></div></li>`}).join('')}</ol>`}
function ticketView(d,r){const rows=sortedTickets(d.tickets).filter(t=>matches([t.id,t.title,t.status,t.claimed_by,t.description],filterNeedle));const visible=!r.ticket||rows.some(t=>t.id===r.ticket);const activeStatuses=['open','claimed','in_progress','creating_report','submitted','reviewing','in_review'];return `${visible?'':`<p class="warning">Requested ticket ${esc(r.ticket)} is outside this bounded response or filter.</p>`}<div class="toolbar"><span>${esc(rows.length)} of ${esc(d.ticket_returned)} returned tickets</span><label>Updated <select id="ticket-sort"><option value="newest"${detailSort==='newest'?' selected':''}>newest first</option><option value="oldest"${detailSort==='oldest'?' selected':''}>oldest first</option></select></label></div><section class="card"><div class="table-scroll"><table><thead><tr><th>Ticket</th><th>Title and details</th><th>Status</th><th class="hide-small">Updated</th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr data-ticket-status="${esc(t.status)}" data-active-ticket-row="${activeStatuses.includes(t.status)}"><td><span class="id">${esc(t.id)}</span></td><td><details class="ticket-detail" data-ticket="${esc(t.id)}" data-state-key="${esc(`ticket:${r.central}:${d.board.board_id}:${t.id}`)}"${r.ticket===t.id?' open':''}><summary>${esc(t.title)}</summary><div class="ticket-detail-body">${ticketCoordination(t)}${ticketLifecycle(t)}<p class="ticket-copy">${esc(t.description||'No description')}</p>${t.required_fields.length?`<div class="required">${t.required_fields.map(x=>`<span class="pill">${esc(x)}</span>`).join('')}</div>`:''}${t.latest_submission_summary?`<p class="meta ticket-copy">Latest submission: ${esc(t.latest_submission_summary)}</p>`:''}${t.review_label?`<p class="meta">Review: ${esc(t.review_label)}</p>`:''}${ticketActivityView(d,r,t)}${handoffView(t,r,d)}${annotationView(t)}</div></details></td><td><span class="status">${esc(t.status)}</span><div class="meta">${esc(t.claimed_by||'')}</div></td><td class="meta hide-small">${esc(fmt(t.updated_at))}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No tickets match the filter.</td></tr>'}</tbody></table></div></section>`;}
function changesFor(events,since,generatedAt){const cutoff=since===null?new Date(generatedAt).getTime()-86400000:null,chosen=events.filter(e=>since!==null?Number.isInteger(e.seq)&&e.seq>since:new Date(e.occurred_at).getTime()>=cutoff),counts={created:0,claimed:0,submitted:0,closed:0,rejected:0};for(const e of chosen){if(e.kind==='ticket_created')counts.created++;if(e.status_to==='claimed')counts.claimed++;if(e.status_to==='submitted')counts.submitted++;if(e.status_to==='closed')counts.closed++;if(e.review_verdict==='reject'||(e.status_from==='submitted'&&['open','claimed','rejected'].includes(e.status_to)&&Number(e.rejection_count)>0))counts.rejected++}return{counts,event_count:chosen.length}}
function changesView(d,r){const valid=r.since!==null&&/^\d+$/.test(r.since),since=valid?Number(r.since):null,events=filterChangeEvents(d.events,filterNeedle),summary=changesFor(events,since,d.generated_at);return `<div class="toolbar"><div><b>${since===null?'Last 24 hours':`After seq ${esc(since)}`}</b><p class="muted">Calculated only from the ${esc(d.event_returned)} returned events.</p></div><form id="changes-form"><label>Starting seq <input id="since-seq" inputmode="numeric" pattern="[0-9]*" value="${since===null?'':esc(since)}" placeholder="blank = 24h"></label> <button type="submit">Apply</button></form></div><section class="strip change-grid">${Object.entries(summary.counts).map(([name,count])=>`<div class="metric"><span>${esc(name)}</span><b>${esc(count)}</b></div>`).join('')}</section><p class="muted">${esc(summary.event_count)} bounded event(s) matched.</p>`}
const flowLabels={open:'Open',claimed:'Working',submitted:'Review',closed_today:'Done'};let flowLane='open';
function flowCardMeta(t,key){const parts=[`Status ${t.status_label||t.status||'Not observed'}`];if(key==='claimed')parts.push(`Agent ${t.claimed_by||'None recorded'}`);if(key==='submitted'){parts.push(`Review wait ${elapsedAge(t.review_wait_started_at)}`);if(Number(t.rejection_count)>0)parts.push(`Rejected ×${Number(t.rejection_count)}`)}return parts}
function selectFlowLane(root,key,moveFocus=false){if(!Object.hasOwn(flowLabels,key))return;flowLane=key;for(const tab of root.querySelectorAll('[role="tab"][data-flow-lane]')){const active=tab.dataset.flowLane===key;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;if(active&&moveFocus)tab.focus()}for(const panel of root.querySelectorAll('[role="tabpanel"][data-flow-panel]'))panel.dataset.active=String(panel.dataset.flowPanel===key)}
function bindFlowTabs(root=document){const tabs=[...root.querySelectorAll('[role="tab"][data-flow-lane]')];for(const tab of tabs){tab.addEventListener('click',()=>selectFlowLane(root,tab.dataset.flowLane));tab.addEventListener('keydown',event=>{const index=tabs.indexOf(tab),last=tabs.length-1;let next=null;if(event.key==='ArrowRight')next=index===last?0:index+1;if(event.key==='ArrowLeft')next=index===0?last:index-1;if(event.key==='Home')next=0;if(event.key==='End')next=last;if(next===null)return;event.preventDefault();selectFlowLane(root,tabs[next].dataset.flowLane,true)})}selectFlowLane(root,flowLane)}
function flowView(d,r){const byId=new Map(d.tickets.map(t=>[t.id,t])),lanes=Object.entries(flowLabels).map(([key,label])=>({key,label,tickets:(d.ticket_flow[key]||[]).map(id=>byId.get(id)).filter(Boolean).filter(t=>matches([t.id,t.title,t.claimed_by,t.status],filterNeedle))}));return `<p class="muted bounded-note">Classified from ${esc(d.ticket_returned)} returned tickets; omitted snapshot rows are not inferred.</p><div class="flow-tabs" role="tablist" aria-label="Ticket flow lanes">${lanes.map(({key,label,tickets})=>`<button id="flow-tab-${esc(key)}" type="button" role="tab" data-flow-lane="${esc(key)}" aria-controls="flow-panel-${esc(key)}" aria-selected="${key===flowLane}">${esc(label)} · ${esc(tickets.length)}</button>`).join('')}</div><section class="flow">${lanes.map(({key,label,tickets})=>`<div id="flow-panel-${esc(key)}" class="flow-column" role="tabpanel" data-flow-panel="${esc(key)}" data-active="${key===flowLane}" aria-labelledby="flow-tab-${esc(key)}"><h3>${esc(label)} · ${esc(tickets.length)}</h3>${tickets.map(t=>`<a class="flow-card${key==='submitted'&&Number(t.rejection_count)>0?' flow-attention':''}" href="${ticketHref(r.central,d.board.board_id,t.id)}"><span class="id">${esc(t.id)}</span><div>${esc(t.title||'Not supplied')}</div>${flowCardMeta(t,key).map(value=>`<span class="meta">${esc(value)}</span>`).join('')}</a>`).join('')||'<p class="empty">None recorded</p>'}</div>`).join('')}</section>`}
const routeStage=stage=>stage?`<b>${esc(stage.label)}</b><span class="meta">${esc(fmt(stage.at))}</span>`:'<span class="muted">—</span>';
function routesView(d,r){const routeData=d.routes||{rows:[],seats:[],row_returned:0,row_total:0,truncated:true,truncation_note:'Routes source unavailable.'},rows=routeData.rows.filter(t=>matches([t.id,t.title,t.status,t.created?.label,t.executed?.label,t.submitted?.label,t.reviewed?.label,t.rework_count],filterNeedle)),seats=routeData.seats.filter(s=>matches([s.label,s.created,s.executed,s.reviewed,s.rework_received_rate],filterNeedle));return `<section id="routes-view"><p class="${routeData.truncated?'warning':'muted'} bounded-note">${esc(routeData.truncation_note)}</p><h3 class="pool">Seat load in the window</h3><section class="route-load" aria-label="Per-seat route totals">${seats.length?seats.map(s=>`<article class="route-seat" data-route-seat="${esc(s.label)}"><b>${esc(s.label)}</b><div class="counts"><span class="pill">created ${esc(s.created)}</span><span class="pill">executed ${esc(s.executed)}</span><span class="pill">reviewed ${esc(s.reviewed)}</span><span class="pill">rework received ${esc(s.rework_received_rate)}% (${esc(s.rework_received)})</span></div></article>`).join(''):'<p class="empty">No seats match the filter.</p>'}</section><p class="muted">Showing ${esc(rows.length)} matching route(s) from ${esc(routeData.row_returned)} returned; ${esc(routeData.row_total)} assembled before row bounds.</p><section class="card pool"><div class="table-scroll"><table aria-label="Ticket provenance routes"><thead><tr><th>Ticket</th><th>Created by</th><th>Executed by</th><th>Submitted by</th><th>Reviewed / closed by</th><th>Rework</th><th>Updated</th></tr></thead><tbody>${rows.length?rows.map(t=>`<tr data-route-ticket="${esc(t.id)}"><td><a class="id" href="${ticketHref(r.central,d.board.board_id,t.id)}">${esc(t.id)}</a><div>${esc(t.title)}</div><span class="status">${esc(t.status)}</span></td><td class="route-stage">${routeStage(t.created)}</td><td class="route-stage">${routeStage(t.executed)}</td><td class="route-stage">${routeStage(t.submitted)}</td><td class="route-stage">${routeStage(t.reviewed)}</td><td>${esc(t.rework_count)}</td><td class="meta">${esc(fmt(t.updated_at))}</td></tr>`).join(''):'<tr><td colspan="7" class="empty">No routes match the filter.</td></tr>'}</tbody></table></div></section></section>`}
function findings(d){if(!d.coordinator_findings)return'';return `<section class="card"><h3>Coordinator findings</h3><div class="finding-list">${d.coordinator_findings.items.map(f=>`<div class="finding"><b>${esc(f.kind)}</b>${f.ticket_id?` <span class="id">${esc(f.ticket_id)}</span>`:''}<p>${esc(f.text)}</p>${f.draft?`<p class="meta">Draft · ${esc(f.draft.category)} · ${esc(f.draft.title)}</p>`:''}</div>`).join('')||'<p class="empty">No current findings</p>'}</div>${d.coordinator_findings.truncated_count?`<p class="warning">${esc(d.coordinator_findings.truncated_count)} findings omitted by the bounded state.</p>`:''}</section>`}
function renderDetail(d){const r=route();if(!r||r.kind!=='board'||r.central!==d.central||r.board!==d.board.board_id)return;syncBoardSelection();const views={tickets:ticketView,timeline:timelineView,changes:changesView,flow:flowView,routes:routesView};document.querySelector('#detail-view').innerHTML=`<a class="back" href="#/">← All centrals</a><div class="top"><div><h2>${esc(d.board.label)} · ${esc(d.central)}</h2><span class="meta">${esc(d.board.board_id)}</span></div>${d.truncated?`<span class="status">${esc(d.ticket_returned)} of ${esc(d.ticket_total)} tickets shown</span>`:''}</div><div class="toolbar">${tabs(d,r)}<span class="muted">Two guarded writes only: config and intake · ${esc(d.central)}</span></div>${intakePanel(d,r)}${r.view==='tickets'?findings(d):''}${views[r.view](d,r)}`;document.querySelector('#intake-form')?.addEventListener('submit',submitIntake);for(const button of document.querySelectorAll('[data-intake-action]'))button.addEventListener('click',decideIntake);document.querySelector('#ticket-sort')?.addEventListener('change',e=>{detailSort=e.target.value;renderDetail(d)});document.querySelector('#changes-form')?.addEventListener('submit',e=>{e.preventDefault();const value=document.querySelector('#since-seq').value.trim();location.hash=`/central/${encodeURIComponent(r.central)}/board/${encodeURIComponent(d.board.board_id)}/changes${value?`?since=${encodeURIComponent(value)}`:''}`});document.querySelector('#state').textContent=`Updated ${fmt(d.generated_at)} · ${esc(d.central)}`;const detailRoot=document.querySelector('#detail-view');bindInteractive(detailRoot);if(r.view==='flow')bindFlowTabs(detailRoot);renderSearchResults();if(r.ticket){const target=[...document.querySelectorAll('[data-ticket]')].find(x=>x.dataset.ticket===r.ticket);if(target){target.open=true;sectionStates.set(target.dataset.stateKey,true);target.scrollIntoView({block:'center'})}}}
const CENTRAL_REQUEST_TIMEOUT_MS=4000;
async function fetchJson(path,options={}){const response=await fetch(path,{cache:'no-store',...options});if(!response.ok){const body=await response.json().catch(()=>null),error=new Error(`HTTP ${response.status}`);error.connectionClass=body&&typeof body.error==='string'?body.error:`HTTP${response.status}`;error.status=response.status;throw error}return response.json()}
async function fetchWithTimeout(path,timeoutMs=CENTRAL_REQUEST_TIMEOUT_MS){const controller=new AbortController();let timer;const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>{controller.abort();const error=new Error('central request timed out');error.connectionClass='TimeoutError';reject(error)},timeoutMs)});try{return await Promise.race([fetchJson(path,{signal:controller.signal}),timeout])}finally{clearTimeout(timer)}}
async function loadCentrals(){const d=await fetchJson('/api/centrals');centralLabels=d.centrals;defaultCentral=d.default}
async function refreshCentral(label,timeoutMs=CENTRAL_REQUEST_TIMEOUT_MS){const key=`fleet:${label}`;try{fleetData[label]=await fetchWithTimeout(`/api/fleet?${apiCentral(label)}`,timeoutMs);delete fleetErrors[label];if(typeof markConnectionSuccess==='function')markConnectionSuccess(key)}catch(e){fleetErrors[label]=connectionFailureDetail(e).errorClass;if(typeof markConnectionFailure==='function')markConnectionFailure(key,e)}finally{if(!route()&&!(typeof refreshPaused==='function'&&refreshPaused()))renderFleet()}}
async function refreshFleet(timeoutMs=CENTRAL_REQUEST_TIMEOUT_MS){if(!centralLabels.length)await loadCentrals();await Promise.allSettled(centralLabels.map(label=>refreshCentral(label,timeoutMs)))}
async function refreshOverhead(){const r=route();if(!r||r.kind!=='overhead')return;const key=`overhead:${r.central}`;try{const data=await fetchJson(`/api/overhead?${apiCentral(r.central)}`);if(route()?.central!==r.central)return;markConnectionSuccess(key);if(refreshPaused())return;renderOverhead(data)}catch(e){markConnectionFailure(key,e);if(!document.querySelector('#detail-view').children.length)document.querySelector('#detail-view').innerHTML=`<a class="back" href="#/">← All centrals</a><p class="error">Overhead unavailable for ${esc(r.central)}.</p>`}}
async function refreshDetail(){const r=route();if(!r||r.kind!=='board')return;const key=`detail:${r.central}:${r.board}`;try{const data=await fetchJson(`/api/board/${encodeURIComponent(r.board)}?${apiCentral(r.central)}`);const current=route();if(current?.central!==r.central||current?.board!==r.board)return;detailData=data;markConnectionSuccess(key);if(refreshPaused())return;renderDetail(data);refreshIntake(current,true)}catch(e){markConnectionFailure(key,e);if(!detailData||detailData.central!==r.central||detailData.board?.board_id!==r.board)document.querySelector('#detail-view').innerHTML=`<a class="back" href="#/">← All centrals</a><p class="error">Board detail unavailable for ${esc(r.central)}.</p>`}}
function syncRoute(){const r=route();document.querySelector('#home-view').hidden=!!r;document.querySelector('#detail-view').hidden=!r||r.kind==='config'||r.kind==='workers';if(detailTimer){clearInterval(detailTimer);detailTimer=null}for(const key of [...connectionFailures])if(key.startsWith('detail:')||key.startsWith('overhead:')){connectionFailures.delete(key);connectionFailureDetails.delete(key)}updateConnectionState();if(r?.kind==='board'){if(detailData?.central===r.central&&detailData?.board?.board_id===r.board)renderDetail(detailData);else document.querySelector('#detail-view').innerHTML='<p class="empty">Loading board detail…</p>';refreshDetail();detailTimer=setInterval(refreshDetail,5000)}else if(r?.kind==='overhead'){document.querySelector('#detail-view').innerHTML='<p class="empty">Loading overhead…</p>';refreshOverhead();detailTimer=setInterval(refreshOverhead,5000)}else if(!r)renderFleet()}
document.querySelector('#filter').addEventListener('input',e=>{filterNeedle=e.target.value.toLocaleLowerCase();searchSelection=0;const r=route();if(r?.kind==='board'&&detailData)renderDetail(detailData);else if(!r)renderFleet();else renderSearchResults()});document.querySelector('#search-results').addEventListener('click',e=>{const target=e.target.closest('[data-search-index]');if(target){e.preventDefault();jumpSearchResult(Number(target.dataset.searchIndex))}});document.querySelector('#theme-toggle').addEventListener('click',()=>{theme=theme==='dark'?'light':'dark';applyPreferences()});document.querySelector('#density-toggle').addEventListener('click',()=>{density=density==='comfortable'?'compact':'comfortable';applyPreferences()});document.querySelector('#help-toggle').addEventListener('click',()=>document.querySelector('#help-overlay').showModal());document.querySelector('#help-close').addEventListener('click',()=>{document.querySelector('#help-overlay').close();document.querySelector('#help-toggle').focus()});document.addEventListener('keydown',handleDashboardKeydown);window.addEventListener('hashchange',syncRoute);applyPreferences();refreshDeployment();loadCentrals().then(()=>{refreshFleet();syncRoute();if(typeof syncConfigRoute==='function')syncConfigRoute();if(typeof syncWorkersRoute==='function')syncWorkersRoute()}).catch(e=>{document.querySelector('#state').textContent='Startup failed';announceState('Startup failed');markConnectionFailure('startup')});setInterval(refreshFleet,5000);

