let attentionState={},attentionStateLoaded=false,attentionStateSaved='';
function loadAttentionState(){return attentionState}
async function saveAttentionState(value){attentionState=value;if(!attentionStateLoaded)return;const encoded=JSON.stringify(value);if(encoded===attentionStateSaved)return;const response=await fetch('/api/attention',{method:'POST',headers:{'Content-Type':'application/json'},body:encoded});if(!response.ok)throw new Error(`attention state HTTP ${response.status}`);attentionStateSaved=encoded}
async function refreshAttentionState(){try{const result=await fetchJson('/api/attention');attentionState=result.items&&typeof result.items==='object'?result.items:{};attentionStateSaved=JSON.stringify(attentionState);attentionStateLoaded=true;if(navKind()==='overview'&&!refreshPaused())renderHub()}catch(_error){attentionStateLoaded=false}}
function attentionCandidates(){const rows=[];for(const [central,d] of Object.entries(fleetData)){for(const b of d.boards||[]){if(b.coordinator_findings_stale)rows.push({key:`coordinator-findings-stale|${central}|${b.board_id}`,fingerprint:'coordinator-findings-stale-15m',type:'coordinator-findings-stale',central,board:b,level:'critical',title:'coordinator findings stale > 15 min',text:'The coordinator findings state has not refreshed for more than 15 minutes.'});for(const f of b.coordinator_findings?.items||[]){rows.push({key:`finding|${central}|${b.board_id}|${f.kind}|${f.ticket_id||''}`,fingerprint:`${f.level}|${f.kind}|${f.text}`,type:'finding',central,board:b,level:f.level||'info',title:f.kind,text:f.text,ticket_id:f.ticket_id})}for(const t of b.tickets||[]){const age=Date.now()-new Date(t.updated_at||Date.now()).getTime();if(t.status==='open'&&age>1800000)rows.push({key:`starved|${central}|${b.board_id}|${t.id}`,fingerprint:'open-over-30m',type:'starved',central,board:b,level:'warn',title:'Starved ticket',text:t.title,ticket_id:t.id,age});const keepaliveAge=numberCount(t.lease_keepalive_only_age_s),keepaliveThreshold=(numberCount(t.ttl_s)||900)*3;if(['claimed','in_progress','creating_report'].includes(t.status)&&t.lease_renewal_source==='keepalive'&&keepaliveAge>keepaliveThreshold){const minutes=Math.floor(keepaliveAge/60),thresholdMinutes=Math.floor(keepaliveThreshold/60);rows.push({key:`keepalive-only|${central}|${b.board_id}|${t.id}`,fingerprint:`keepalive-only-${t.id}-${keepaliveThreshold}`,type:'keepalive-only',central,board:b,level:'critical',title:`Claim renewed only by keepalive for > ${thresholdMinutes} minutes`,text:`${t.claimed_by||'Unknown seat'} · ${minutes} minutes · ${t.title}`,ticket_id:t.id,age:keepaliveAge*1000})}if((t.abandoned_count||0)>0)rows.push({key:`lease-lapsed|${central}|${b.board_id}|${t.id}`,fingerprint:`lease-lapsed-${t.abandoned_count}`,type:'lease-lapsed',central,board:b,level:'warn',title:`Lease lapsed ${t.abandoned_count} times`,text:t.title,ticket_id:t.id,age});const expired=(t.dispatch_history||[]).filter(h=>h.state==='expired');if(expired.length>0){const names=[...new Set(expired.map(h=>h.agent_name||h.agent_id).filter(Boolean))];rows.push({key:`dispatch-non-acting|${central}|${b.board_id}|${t.id}`,fingerprint:`dispatch-non-acting-${t.id}-${expired.length}`,type:'dispatch',central,board:b,level:'warn',title:'Offers going to non-acting identities',text:`${t.title} · ${expired.length} expired offer(s) to ${names.join(', ')||'unnamed'}`,ticket_id:t.id,age})}}}for(const p of hubOverhead[central]?.sessions||[]){if(p.pressure==='ok')continue;rows.push({key:`context|${central}|${p.board_id}|${p.agent_name}`,fingerprint:`${p.pressure}|${p.mode||'unknown'}|${p.reason||''}`,type:'context',central,board:{board_id:p.board_id,label:p.board_id},level:p.pressure==='compact'||p.pressure==='anomaly'?'critical':'warn',title:p.pressure==='anomaly'?'Context stats anomaly':`Context ${p.pressure}`,text:p.pressure==='anomaly'?`${p.agent_name} · raw wait-return record requires inspection`:`${p.agent_name} · ${p.estimated_tokens_per_return??p.latest_estimated_tokens} tokens / return · ${p.estimated_tokens_per_hour??'—'} / hour · ${p.mode||'unknown'}${p.reason?' · '+p.reason:''}`})}for(const p of hubOverhead[central]?.push_unavailable||[]){rows.push({key:`push-unavailable|${central}|${p.board_id}|${p.agent_name}`,fingerprint:`${p.reason}|${p.observed_at}`,type:'push-unavailable',central,board:{board_id:p.board_id,label:p.board_id},level:'critical',title:'Push unavailable',text:p.warning||`push unavailable: ${p.reason}`})}}return rows}
function reconcileAttention(){const now=new Date(),before=loadAttentionState(),next={},visible=[];for(const item of attentionCandidates()){if(!item.key||next[item.key])continue;const old=before[item.key],same=old?.fingerprint===item.fingerprint;const row={fingerprint:item.fingerprint,first_seen:same&&old.first_seen?old.first_seen:now.toISOString(),last_seen:now.toISOString(),acknowledged:same&&old.acknowledged===true,snooze_until:same?old.snooze_until||null:null};next[item.key]=row;const snoozed=row.snooze_until&&new Date(row.snooze_until)>now;if(!row.acknowledged&&!snoozed)visible.push({...item,...row})}saveAttentionState(next).catch(()=>{});window.__fleetAttentionPanel={generated_at:now.toISOString(),items:visible.map(x=>({key:x.key,type:x.type,central:x.central,board_id:x.board.board_id,ticket_id:x.ticket_id||null,first_seen:x.first_seen,last_seen:x.last_seen}))};return visible}
function attentionRow(x){const link=x.ticket_id?`<a class="id" href="${ticketHref(x.central,x.board.board_id,x.ticket_id)}">${esc(x.ticket_id)}</a>`:`<a href="${centralHref(x.central,'overhead')}">Inspect</a>`;return `<div class="finding-row"><span class="severity ${esc(x.level)}"></span><div><b>${esc(x.title)}</b><p>${esc(x.text)}</p><span class="meta">${esc(x.central)} · ${esc(x.board.label)} · first seen ${esc(fmt(x.first_seen))}</span><div class="attention-actions"><button type="button" data-attention-action="ack" data-attention-key="${esc(x.key)}">Acknowledge</button><button type="button" data-attention-action="snooze" data-attention-key="${esc(x.key)}">Snooze 24h</button></div></div>${link}</div>`}
function humanRequestRows(){const rows=[];for(const [central,d] of Object.entries(fleetData)){for(const b of d.boards||[]){for(const h of b.human_requests||[]){rows.push({central,board:b,h})}}}return rows}
function butlerHoldRows(){const rows=[];for(const [central,d] of Object.entries(fleetData)){for(const b of d.boards||[]){for(const f of b.coordinator_findings?.items||[]){if(f.kind==='would_answer'&&f.question_id&&['shadow','pending'].includes(f.hold?.status))rows.push({central,board:b,f})}}}return rows}
function butlerEvaluation(row){return(row.board.coordinator_findings?.butler_evaluations||[]).find(item=>item.question_id===row.f.question_id&&item.ticket_id===row.f.ticket_id)}
function butlerAgreementRows(){const rows=[];for(const [central,d] of Object.entries(fleetData))for(const b of d.boards||[])for(const score of b.coordinator_findings?.agreement_by_question_kind||[])rows.push({central,board:b,score});return rows}
function butlerTicketAgreementRows(){const rows=[];for(const [central,d] of Object.entries(fleetData))for(const b of d.boards||[])for(const score of b.coordinator_findings?.agreement_by_ticket||[])rows.push({central,board:b,score});return rows}
function butlerRepeatedTicketRows(){const rows=[];for(const [central,d] of Object.entries(fleetData))for(const b of d.boards||[])for(const ticket of b.coordinator_findings?.multi_question_tickets||[])rows.push({central,board:b,ticket});return rows}
function butlerEvaluationTruncationRows(){const rows=[];for(const [central,d] of Object.entries(fleetData))for(const b of d.boards||[]){const count=b.coordinator_findings?.butler_evaluation_truncated||0;if(count)rows.push({central,board:b,count})}return rows}
function humanUrlHost(url){try{return new URL(url).host}catch(_error){return String(url)}}
function butlerMarkButton(row,value,label){const f=row.f||{};return `<button type="button" data-butler-mark="${esc(value)}" data-central="${esc(row.central)}" data-board="${esc(row.board.board_id)}" data-ticket="${esc(f.ticket_id)}" data-question="${esc(f.question_id)}">${esc(label)}</button>`}
function butlerHoldCard(row){const f=row.f||{},hold=f.hold||{},evaluation=butlerEvaluation(row),link=f.ticket_id?`<a class="id" href="${ticketHref(row.central,row.board.board_id,f.ticket_id)}">${esc(f.ticket_id)}</a>`:'',precedents=(f.precedents||[]).map(p=>`<a class="id" href="${ticketHref(row.central,row.board.board_id,p.ticket_id)}">${esc(p.question_id)} · ${esc(p.ticket_id)}</a>`).join(' · '),mark=evaluation?.mark,isDraft=evaluation?.draft_status==='produced',buttons=isDraft?[['send_as_is','Would send as is'],['needed_edits','Needed edits'],['wrong','Wrong'],['should_have_escalated','Should have escalated']]:[['correct_escalation','Correct escalation'],['should_have_answered','Should have answered']],marking=mark?`<p class="meta">Human mark: ${esc(mark.replaceAll('_',' '))}</p>`:`<div class="attention-actions">${buttons.map(([value,label])=>butlerMarkButton(row,value,label)).join('')}</div>`;return `<div class="finding-row"><span class="severity warn"></span><div><b>Waiting for you · board butler hold</b><p>${esc(f.text||'Evidence-backed draft')}</p><span class="meta">${esc(row.central)} · ${esc(row.board.label)} · ${esc(f.question_id)} · ${esc(f.verdict||'unknown')} · release ${esc(fmt(hold.release_at))}</span>${f.evidence?`<p class="meta">${esc(f.evidence)}</p>`:''}<p class="meta">Precedent: ${precedents||'No precedent found'}</p>${marking}<p class="meta">Veto with board_butler.py --veto-question ${esc(f.question_id)} --control-reason &lt;reason&gt;</p></div>${link}</div>`}
function butlerScoreCard(row){const s=row.score||{},counts=s.marks||{},group=s.question_kind||s.ticket_id||'unknown',success=s.axis==='draft_quality'?'would send as is':'correct escalations',result=s.status==='measured'?`${esc(s.agreement_percent)}% ${success}`:s.status==='incomplete_bounded_state'?'Agreement unavailable: bounded state may omit evaluation records.':`Too few samples (${esc(s.sample_count)}/${BUTLER_MIN_SAMPLES})`,details=s.axis==='draft_quality'?`send as is ${esc(counts.send_as_is||0)} · needed edits ${esc(counts.needed_edits||0)} · wrong ${esc(counts.wrong||0)}`:`correct escalation ${esc(counts.correct_escalation||0)} · should have answered ${esc(counts.should_have_answered||0)} · should have escalated ${esc(counts.should_have_escalated||0)}`;return `<div class="finding-row"><span class="severity"></span><div><b>Butler agreement · ${esc(group)} · ${esc(s.axis)}</b><p>${result}</p><span class="meta">${esc(row.central)} · ${esc(row.board.label)} · ${esc(s.population)} · ${details}</span></div></div>`}
function butlerRepeatedTicketCard(row){const t=row.ticket||{};return `<div class="finding-row"><span class="severity"></span><div><b>Repeated questions · ${esc(t.ticket_id)}</b><p>${esc(t.question_count)} questions</p><span class="meta">${esc(row.central)} · ${esc(row.board.label)}</span></div><a class="id" href="${ticketHref(row.central,row.board.board_id,t.ticket_id)}">${esc(t.ticket_id)}</a></div>`}
const BUTLER_MIN_SAMPLES=3;
function renderWaitingForYou(){const humans=humanRequestRows(),holds=butlerHoldRows(),scores=butlerAgreementRows(),ticketScores=butlerTicketAgreementRows(),repeated=butlerRepeatedTicketRows(),truncated=butlerEvaluationTruncationRows(),count=humans.length+holds.length,truncationWarning=truncated.map(row=>`<p class="warning">Agreement unavailable for ${esc(row.board.label)}: bounded state omitted ${esc(row.count)} state record(s).</p>`).join('');return `<div class="section-title"><h3>Waiting for you</h3><span class="status">${count} pending</span></div><section class="attention-card">${humans.map(humanRequestCard).join('')}${holds.map(butlerHoldCard).join('')||(!humans.length?'<p class="empty">No tickets or held drafts are waiting for a human answer.</p>':'')}</section><div class="section-title"><h3>Butler agreement by question kind</h3><span class="status">human marks only</span></div><section class="attention-card">${truncationWarning}${scores.map(butlerScoreCard).join('')||(!truncated.length?'<p class="empty">No human marks yet. No question kind is trusted.</p>':'')}</section><div class="section-title"><h3>Butler agreement by ticket</h3><span class="status">human marks only</span></div><section class="attention-card">${ticketScores.map(butlerScoreCard).join('')||(!truncated.length?'<p class="empty">No marked tickets yet.</p>':'')}</section><div class="section-title"><h3>Tickets with repeated questions</h3></div><section class="attention-card">${repeated.map(butlerRepeatedTicketCard).join('')||(!truncated.length?'<p class="empty">No ticket has generated more than one recorded question.</p>':'')} ${truncationWarning}</section>`}
function renderAttentionOverview(){const centrals=centralLabels.map(label=>{const d=fleetData[label],error=fleetErrors[label];if(!d)return `<article class="health-card"><div class="signal"><span class="signal-dot bad"></span><b>${esc(label)}</b></div><p class="error">${esc(error||'Connecting…')}</p></article>`;const s=d.pool_summary||{},heartbeat=(d.boards||[]).map(b=>b.coordinator_heartbeat).filter(Boolean).sort().at(-1),tc={open:0,claimed:0,submitted:0,closed_today:0};for(const b of d.boards||[])for(const k in tc)tc[k]+=numberCount((b.counts||{})[k]);return `<article class="health-card"><div class="signal"><span class="signal-dot"></span><b>${esc(label)}</b><span class="status">central up</span></div><p class="meta">Coordinator heartbeat ${esc(heartbeat?fmt(heartbeat):'not observed')}</p><div class="health-metrics"><span>Online<b>${esc(s.online||0)}</b></span><span>Busy<b>${esc(s.busy||0)}</b></span><span>Ready<b>${esc(s.available||0)}</b></span><span>Stale<b>${esc(s.stale||0)}</b></span></div><div class="health-metrics"><span>Open<b>${esc(tc.open)}</b></span><span>Claimed<b>${esc(tc.claimed)}</b></span><span>Submitted${tc.submitted?' ⚠':''}<b>${esc(tc.submitted)}</b></span><span>Closed today<b>${esc(tc.closed_today)}</b></span></div></article>`}).join('');const surfaced=reconcileAttention().sort((a,b)=>(b.level==='critical')-(a.level==='critical')||(b.age||0)-(a.age||0)),attention=surfaced.slice(0,10);return `${pageHead('Home','Fleet overview','Health and attention across every central.')}<section class="health-grid">${centrals||'<div class="skeleton"></div>'}</section>${renderWaitingForYou()}<div class="section-title"><h3>Needs attention</h3><span class="status">${surfaced.length} surfaced</span></div><section class="attention-card">${attention.map(attentionRow).join('')||'<p class="empty">Nothing needs attention. The fleet is calm.</p>'}</section>`}
function renderAttentionBoardsHub(){const cards=[];for(const [central,d] of Object.entries(fleetData))for(const b of d.boards||[]){const total=Object.values(b.counts||{}).reduce((sum,v)=>sum+numberCount(v),0),tr=b.snapshot_truncation,info=tr&&tr.total>tr.returned?`<span class="status">snapshot truncated to ${esc(tr.returned)} of ${esc(tr.total)} tickets</span>`:'';cards.push(`<article class="board-card" data-board-id="${esc(b.board_id)}" data-central="${esc(central)}"><div><p class="eyebrow">${esc(central)}</p><h3>${esc(b.label)}</h3><span class="meta">${esc(b.board_id)} · ${esc(total)} visible tickets</span> ${info}</div><div class="counts">${Object.entries(b.counts||{}).map(([k,v])=>`<span class="pill">${esc(k.replace('_',' '))} <b>${esc(v)}</b></span>`).join('')}</div><div class="card-actions"><a class="primary-action" href="${boardHref(central,b.board_id)}">Workspace</a><a href="${boardHref(central,b.board_id,'flow')}">Flow</a><a href="${boardHref(central,b.board_id,'timeline')}">Timeline</a><a href="${boardHref(central,b.board_id,'changes')}">Changes</a><a href="${boardHref(central,b.board_id,'routes')}">Routes</a></div></article>`)}return `${pageHead('Boards','Board workspaces','Open one board, then move through tickets, findings, intake, flow, timeline, changes, and routes.')}<section class="boards-list">${cards.join('')||'<div class="skeleton"></div>'}</section>`}
function humanEnumOptions(prop){const p=prop&&typeof prop==='object'?prop:{};const source=p.type==='array'&&p.items&&typeof p.items==='object'?p.items:p;const options=[];if(Array.isArray(source.enum)){for(const value of source.enum)options.push({value:String(value),title:String(value)})}else if(Array.isArray(source.oneOf)){for(const arm of source.oneOf){if(arm&&typeof arm==='object'&&'const' in arm)options.push({value:String(arm.const),title:String(arm.title??arm.const)});else if(arm&&typeof arm==='object'&&Array.isArray(arm.enum))for(const value of arm.enum)options.push({value:String(value),title:String(value)})}}return options}
function humanFormField(name,prop,required=false){const p=prop&&typeof prop==='object'?prop:{};const title=esc(String(p.title||name))+(required?' *':'');const requiredAttr=required?' required aria-required="true"':'';const enumOptions=humanEnumOptions(p);if(enumOptions.length){if(p.type==='array'){const defaults=Array.isArray(p.default)?p.default.map(String):[];const minItems=Math.max(Number.isInteger(p.minItems)?p.minItems:0,required?1:0);return `<fieldset class="human-field" data-human-group="${esc(name)}" data-human-required="${required?'true':'false'}" data-human-min-items="${minItems}"><legend>${title}</legend><span>${enumOptions.map(option=>`<label class="human-multi"><input type="checkbox" data-human-field="${esc(name)}" data-human-type="multi-enum" value="${esc(option.value)}" ${defaults.includes(option.value)?'checked':''}> ${esc(option.title)}</label>`).join('')}</span></fieldset>`}const defaultValue=p.default===undefined?'':String(p.default);return `<label class="human-field"><span>${title}</span><select data-human-field="${esc(name)}" data-human-type="enum"${requiredAttr}><option value="">—</option>${enumOptions.map(option=>`<option value="${esc(option.value)}" ${option.value===defaultValue?'selected':''}>${esc(option.title)}</option>`).join('')}</select></label>`}if(p.type==='boolean'){return `<label class="human-field"><input type="checkbox" data-human-field="${esc(name)}" data-human-type="boolean" data-human-required="${required?'true':'false'}" ${p.default===true?'checked':''}> <span>${title}</span></label>`}if(p.type==='number'||p.type==='integer'){return `<label class="human-field"><span>${title}</span><input type="number" step="${p.type==='integer'?'1':'any'}" data-human-field="${esc(name)}" data-human-type="${p.type}" value="${p.default!==undefined?esc(String(p.default)):''}"${requiredAttr}></label>`}return `<label class="human-field"><span>${title}</span><input type="text" data-human-field="${esc(name)}" data-human-type="string" value="${p.default!==undefined?esc(String(p.default)):''}"${requiredAttr}></label>`}
function humanFormContent(form){const content={};const seen=new Set();for(const el of form.querySelectorAll('[data-human-field]')){const name=el.dataset.humanField;if(seen.has(name))continue;seen.add(name);const type=el.dataset.humanType||'string';if(type==='multi-enum'){const values=[...form.querySelectorAll('[data-human-field="'+name+'"]:checked')].map(x=>String(x.value));const group=form.querySelector('[data-human-group="'+name+'"]');const minItems=Number(group?.dataset.humanMinItems||0);if(values.length<minItems)throw new Error(`${name} requires at least ${minItems} selection${minItems===1?'':'s'}`);content[name]=values}else if(type==='boolean'){content[name]=Boolean(el.checked)}else if(type==='number'||type==='integer'){if(el.value!=='')content[name]=Number(el.value);else if(el.required)throw new Error(`${name} is required`)}else if(el.value!==''){content[name]=String(el.value)}else if(el.required)throw new Error(`${name} is required`)}return content}
function humanRequestCard(row){const h=row.h||{};const schema=h.requested_schema&&typeof h.requested_schema==='object'?h.requested_schema:{};const props=schema.properties&&typeof schema.properties==='object'?schema.properties:{};const required=new Set(Array.isArray(schema.required)?schema.required.map(String):[]);const link=h.ticket_id?`<a class="id" href="${ticketHref(row.central,row.board.board_id,h.ticket_id)}">${esc(h.ticket_id)}</a>`:'';let body;if(h.url){body=`<p class="human-url-host">External hand-off on <b>${esc(humanUrlHost(h.url))}</b> (opens in a new tab only on click)</p><a class="button" href="${esc(h.url)}" target="_blank" rel="noopener noreferrer">Open ${esc(humanUrlHost(h.url))} ↗</a>`}else if(h.form_safe===false){body=`<p class="human-safe-fallback">${esc(h.safety_reason||'Form elicitation is disabled for secrets or credentials. A trusted URL is required.')}</p>`}else{const fields=Object.entries(props).map(([name,prop])=>humanFormField(name,prop,required.has(String(name)))).join('');body=`<form class="human-form" data-central="${esc(row.central)}" data-board="${esc(row.board.board_id)}" data-ticket="${esc(h.ticket_id||'')}" data-request="${esc(h.request_id||'')}">${fields}<label class="human-field"><span>Disposition *</span><select data-human-disposition required><option value="reopen">reopen — resume the ticket with this answer</option><option value="park">park — keep the ticket waiting</option><option value="cancel">cancel — cancel the ticket</option></select></label><div class="attention-actions"><button type="button" class="primary-action" data-human-action="accept">Accept</button><button type="button" data-human-action="decline">Decline</button></div><p class="meta human-status"></p></form>`}return `<div class="finding-row"><span class="severity critical"></span><div><b>Waiting for you · ${esc(h.kind||'request')}</b><p>${esc(h.message||'')}</p><span class="meta">${esc(row.central)} · ${esc(row.board.label)} · asked by ${esc(h.asked_by||'unknown')}${h.asked_at?' · '+esc(fmt(h.asked_at)):''}</span>${body}</div>${link}</div>`}
refreshAttentionState();

/*__FLEET_SCRIPT_BOUNDARY__*/

const legacyRouteV1=route,legacyRefreshCentralV1=refreshCentral;
const hubKinds=new Set(['boards','agents','operations']);
let hubWorkers={},hubOverhead={},hubGuide=null,hubExtrasBusy=false,agentFilters={role:'all',status:'all',board:'all',client:'all'};
route=function(){const special=location.hash.match(/^#\/(boards|agents|operations)$/);return special?{kind:special[1]}:legacyRouteV1()};
function navKind(){const r=route();if(!r)return'overview';if(hubKinds.has(r.kind))return r.kind;if(r.kind==='board')return'boards';if(r.kind==='workers')return'agents';return'operations'}
function syncNav(){const kind=navKind(),aliases={overview:'home',boards:'projects',seats:'settings'};for(const link of document.querySelectorAll('[data-nav]')){const active=(aliases[link.dataset.nav]||link.dataset.nav)===kind;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')}}
function pageHead(kicker,title,copy,action=''){return `<header class="page-head"><div><p class="eyebrow">${esc(kicker)}</p><h2>${esc(title)}</h2><p class="muted">${esc(copy)}</p></div>${action}</header>`}
function numberCount(value){const parsed=Number(String(value??0).replace('>=',''));return Number.isFinite(parsed)?parsed:0}
function renderOverview(){const centrals=centralLabels.map(label=>{const d=fleetData[label],error=fleetErrors[label];if(!d)return `<article class="health-card"><div class="signal"><span class="signal-dot bad"></span><b>${esc(label)}</b></div><p class="error">${esc(error||'Connecting…')}</p></article>`;const s=d.pool_summary||{},heartbeat=(d.boards||[]).map(b=>b.coordinator_heartbeat).filter(Boolean).sort().at(-1),tc={open:0,claimed:0,submitted:0,closed_today:0};for(const b of d.boards||[])for(const k in tc)tc[k]+=(b.counts||{})[k]||0;return `<article class="health-card"><div class="signal"><span class="signal-dot"></span><b>${esc(label)}</b><span class="status">central up</span></div><p class="meta">Coordinator heartbeat ${esc(heartbeat?fmt(heartbeat):'not observed')}</p><div class="health-metrics"><span>Busy<b>${esc(s.busy||0)}</b></span><span>Ready<b>${esc(s.available||0)}</b></span><span>Stale<b>${esc(s.stale||0)}</b></span></div><div class="health-metrics"><span>Open<b>${esc(tc.open)}</b></span><span>Claimed<b>${esc(tc.claimed)}</b></span><span>Submitted${tc.submitted?' ⚠':''}<b>${esc(tc.submitted)}</b></span><span>Closed today<b>${esc(tc.closed_today)}</b></span></div></article>`}).join('');const findings=[],starved=[],pressure=[];for(const [central,d] of Object.entries(fleetData)){for(const b of d.boards||[]){for(const f of b.coordinator_findings?.items||[])findings.push({...f,central,board:b});for(const t of b.tickets||[]){const age=Date.now()-new Date(t.updated_at||Date.now()).getTime();if(t.status==='open'&&age>1800000)starved.push({...t,central,board:b,age})}}for(const p of hubOverhead[central]?.sessions||[])if(p.pressure!=='ok')pressure.push({...p,central})}findings.sort((a,b)=>(b.level==='critical')-(a.level==='critical'));starved.sort((a,b)=>b.age-a.age);pressure.sort((a,b)=>(b.pressure_rank||0)-(a.pressure_rank||0));const attention=[...findings.slice(0,5).map(f=>`<div class="finding-row"><span class="severity ${esc(f.level)}"></span><div><b>${esc(f.kind)}</b><p>${esc(f.text)}</p><span class="meta">${esc(f.central)} · ${esc(f.board.label)}</span></div>${f.ticket_id?`<a class="id" href="${ticketHref(f.central,f.board.board_id,f.ticket_id)}">${esc(f.ticket_id)}</a>`:''}</div>`),...pressure.slice(0,4).map(p=>`<div class="finding-row"><span class="severity ${p.pressure==='compact'?'critical':''}"></span><div><b>Context ${esc(p.pressure)}</b><p>${esc(p.agent_name)} · ${esc(p.latest_estimated_tokens)} tokens / poll</p></div><a href="${centralHref(p.central,'overhead')}">Inspect</a></div>`),...starved.slice(0,5).map(t=>`<div class="finding-row"><span class="severity"></span><div><b>Starved ticket</b><p>${esc(t.title)}</p><span class="meta">${esc(t.central)} · ${esc(t.board.label)}</span></div><a class="id" href="${ticketHref(t.central,t.board.board_id,t.id)}">${esc(t.id)}</a></div>`)].slice(0,10);return `${pageHead('Home','Fleet overview','Health and attention across every central.')}<section class="health-grid">${centrals||'<div class="skeleton"></div>'}</section><div class="section-title"><h3>Needs attention</h3><span class="status">${attention.length} surfaced</span></div><section class="attention-card">${attention.join('')||'<p class="empty">Nothing needs attention. The fleet is calm.</p>'}</section>`}
function renderBoardsHub(){const cards=[];for(const [central,d] of Object.entries(fleetData))for(const b of d.boards||[]){const total=Object.values(b.counts||{}).reduce((sum,v)=>sum+numberCount(v),0);cards.push(`<article class="board-card"><div><p class="eyebrow">${esc(central)}</p><h3>${esc(b.label)}</h3><span class="meta">${esc(b.board_id)} · ${esc(total)} visible tickets</span></div><div class="counts">${Object.entries(b.counts||{}).map(([k,v])=>`<span class="pill">${esc(k.replace('_',' '))} <b>${esc(v)}</b></span>`).join('')}</div><div class="card-actions"><a class="primary-action" href="${boardHref(central,b.board_id)}">Workspace</a><a href="${boardHref(central,b.board_id,'flow')}">Flow</a><a href="${boardHref(central,b.board_id,'timeline')}">Timeline</a><a href="${boardHref(central,b.board_id,'changes')}">Changes</a><a href="${boardHref(central,b.board_id,'routes')}">Routes</a></div></article>`)}return `${pageHead('Boards','Board workspaces','Open one board, then move through tickets, findings, intake, flow, timeline, changes, and routes.')}<section class="boards-list">${cards.join('')||'<div class="skeleton"></div>'}</section>`}
function workerByName(central,name){return (hubWorkers[central]?.workers||[]).find(w=>w.name===name)}
function agentIdentity(a){if(a.agent_id)return String(a.agent_id);const name=a.agent_name||a.name;if(a.principal_id&&name)return`${a.principal_id}:${name}`;return String(a.principal_id||name||'unknown')}
function agentIdentityLabel(a){const value=agentIdentity(a);return value.length>12?'…'+value.slice(-12):value}
function workerForAgent(central,a){const workers=hubWorkers[central]?.workers||[],identity=agentIdentity(a),exact=workers.find(w=>agentIdentity(w)===identity);if(exact)return exact;const matches=workers.filter(w=>w.name===a.agent_name),liveMatches=(fleetData[central]?.agents||[]).filter(live=>live.agent_name===a.agent_name);return matches.length===1&&liveMatches.length===1?matches[0]:null}
function renderRoleChips(seats,fallback,scope){const roles=[];for(const s of seats||[]){if(!s.role||!s.board_id)continue;roles.push({board_id:s.board_id,role:s.role})}const unique=new Set(roles.map(r=>r.role)),active=[...new Set(scope?.active_boards||[])],joined=[...new Set(roles.map(r=>r.board_id))],fullRegistry=scope?.mode==='registry'&&scope?.status==='full'&&active.length>1&&active.every(board=>joined.includes(board))&&joined.every(board=>active.includes(board));let chips;if(!roles.length)chips=esc(fallback||'worker');else if(unique.size===1&&fullRegistry){const role=roles[0].role,boards=roles.map(r=>esc(r.board_id)).join(', ');chips='<span class="role-chip" title="'+esc(role)+' on '+boards+'">'+esc(role)+' (all boards)</span>'}else chips=roles.map(r=>'<span class="role-chip" title="'+esc(r.board_id)+': '+esc(r.role)+'"><span class="chip-board">'+esc(r.board_id)+'</span>: <span class="chip-role">'+esc(r.role)+'</span></span>').join('');if(scope?.status==='partial'){const missing=(scope.missing_boards||[]).join(', ')||'unknown';chips+='<span class="warning scope-state">partial registry · missing '+esc(missing)+'</span>'}else if(scope?.status==='misconfigured'){chips+='<span class="warning scope-state">scope misconfigured</span>'}return chips}
function agentRoles(a,managed){return[...new Set([...(a.seats||[]).map(s=>s.role),managed?.role].filter(Boolean))]}
function canonicalAgentClient(value){const client=String(value||'').trim();if(!client)return'';const lower=client.toLocaleLowerCase();if(lower.startsWith('codex'))return'codex';if(lower.includes('goose'))return'goose';if(lower.includes('aion'))return'AionUi';return client}
function agentClients(a,managed){return[...new Set([...(a.seats||[]).flatMap(s=>[s.client,s.capabilities?.host]),managed?.host].map(canonicalAgentClient).filter(Boolean))]}
function agentBoards(a){return[...new Set([...(a.boards||[]),...(a.seats||[]).map(s=>s.board_id)].filter(Boolean))]}
function agentTier(a,managed){const tiers=[...(a.seats||[]).map(s=>s.tier??s.capabilities?.tier_max),managed?.tier_max,managed?.max_tier].filter(v=>v!==undefined&&v!==null&&v!=='');return tiers.length?tiers[0]:'—'}
function agentDisplayState(a,managed){if(managed?.running===false)return'offline';if(a.pool_status==='busy'||a.pool_status==='working')return'working';if(a.pool_status==='available')return'available';if(a.pool_status==='connected')return'connected';if(a.pool_status==='stale')return'stale';if(a.pool_status==='offline'||a.pool_status==='unreachable')return'offline';return'offline'}
function detailedAge(value,now=Date.now()){if(!value)return'not observed';const then=new Date(value).getTime();if(!Number.isFinite(then))return'not observed';const minutes=Math.max(0,Math.floor((now-then)/60000));if(minutes<1)return'less than 1m ago';if(minutes<60)return`${minutes}m ago`;const hours=Math.floor(minutes/60),rest=minutes%60;if(hours<24)return`${hours}h ${rest}m ago`;const days=Math.floor(hours/24),remaining=hours%24;return`${days}d ${remaining}h ago`}
function leaseCountdown(value,now=Date.now()){if(!value)return'Lease not observed';const expires=new Date(value).getTime();if(!Number.isFinite(expires))return'Lease not observed';const seconds=Math.floor((expires-now)/1000);if(seconds<=0)return'Lease expired';const hours=Math.floor(seconds/3600),minutes=Math.floor((seconds%3600)/60),rest=seconds%60;return`Lease ${hours?hours+'h ':''}${minutes}m ${rest}s`}
function agentMatchesFilters(record){const a=record.agent,managed=workerForAgent(record.central,a),roles=agentRoles(a,managed),boards=agentBoards(a),clients=agentClients(a,managed),state=agentDisplayState(a,managed);return(agentFilters.role==='all'||roles.includes(agentFilters.role))&&(agentFilters.status==='all'||state===agentFilters.status)&&(agentFilters.board==='all'||boards.includes(agentFilters.board))&&(agentFilters.client==='all'||clients.includes(agentFilters.client))}
function agentFilterOptions(records,key,label,values){const selected=agentFilters[key],options=[...new Set(values.filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b)));return`<label>${esc(label)}<select data-agent-filter="${esc(key)}"><option value="all">All</option>${options.map(value=>`<option value="${esc(value)}" ${selected===value?'selected':''}>${esc(value)}</option>`).join('')}</select></label>`}
function agentCountStrip(records){const states=[['working','◉','Working / กำลังทำงาน'],['available','○','Available / พร้อม'],['connected','◇','Connected / not dispatch-ready'],['stale','△','Stale / ไม่เคลื่อนไหว'],['offline','×','Offline / unreachable']];return`<section class="agent-count-strip" aria-label="Seat status counts" data-pursers-panel="agents" data-pursers-state="ready">${states.map(([state,glyph,label])=>{const count=records.filter(record=>agentDisplayState(record.agent,workerForAgent(record.central,record.agent))===state).length;return`<button type="button" data-agent-status-filter="${state}" data-pursers-status="${state}" aria-pressed="${agentFilters.status===state}"><span class="state-glyph" aria-hidden="true">${glyph}</span><span>${label}</span><b>${count}</b></button>`}).join('')}</section>`}
function agentFilterBar(records){const roles=records.flatMap(record=>agentRoles(record.agent,workerForAgent(record.central,record.agent))),boards=records.flatMap(record=>agentBoards(record.agent)),clients=records.flatMap(record=>agentClients(record.agent,workerForAgent(record.central,record.agent)));return`<div class="agent-filters" aria-label="Filter seats">${agentFilterOptions(records,'role','Role',roles)}${agentFilterOptions(records,'status','Status',['working','available','connected','stale','offline'])}${agentFilterOptions(records,'board','Board',boards)}${agentFilterOptions(records,'client','Client / platform',clients)}<button type="button" data-agent-filter-reset>Reset filters</button></div>`}
// merge retained rc6 identity-safe live card below; the combined override follows the main timing renderer.
function liveAgentCardTimingV1IdentityV1(central,a){const managed=workerForAgent(central,a),liveWork=agentLiveWork(a),managedWork=managed?.current_work||[],work=[...liveWork,...managedWork.filter(x=>!liveWork.some(s=>s.board_id===x.board_id&&s.current_ticket_id===x.ticket_id))],identity=agentIdentityLabel(a),duplicate=a.duplicate_name?`<span class="warning">Duplicate name · identity ${esc(identity)}</span>`:`<span class="meta">Identity ${esc(identity)}</span>`;return `<article class="agent-card" data-agent-identity="${esc(agentIdentity(a))}"><div class="agent-card-head"><div><span class="agent-role">${renderRoleChips(a.seats,managed?.role||'worker',a.board_scope)}</span><h3>${esc(a.agent_name)}</h3><span class="meta">${esc(central)} · ${esc((a.boards||[]).join(', '))}</span>${duplicate}</div><div class="agent-card-state"><span class="status">${esc(a.pool_status)}</span><span class="meta">${esc(relativeAge(a.last_seen))}</span></div></div>${work.length?work.map(s=>`<div class="work-row"><span class="severity"></span><div>${agentTicketLink(central,s)}<span class="meta">${esc(s.project||`${s.role||managed?.role||'worker'} · ${s.board_id}`)}</span></div></div>`).join(''):'<p class="empty">ว่าง/idle</p>'}${managed?managedControls(central,managed,false):'<span class="meta">Live pool seat · not locally managed</span>'}</article>`}
// merge retained main roster-timing live card below.
function liveAgentCardTimingV1(central,a){const managed=workerByName(central,a.agent_name),liveWork=agentLiveWork(a),managedWork=managed?.current_work||[],work=[...liveWork,...managedWork.filter(x=>!liveWork.some(s=>s.board_id===x.board_id&&s.current_ticket_id===x.ticket_id))];return `<article class="agent-card"><div class="agent-card-head"><div><span class="agent-role">${renderRoleChips(a.seats,managed?.role||'worker',a.board_scope)}</span><h3>${esc(a.agent_name)}</h3><span class="meta">${esc(central)} · ${esc((a.boards||[]).join(', ')||'None recorded')}</span></div><div class="agent-card-state"><span class="status">${esc(a.pool_status||'Not observed')}</span><span class="meta">Last seen ${esc(relativeAge(a.last_seen))}</span></div></div>${work.length?work.map(s=>`<div class="work-row"><span class="severity${a.pool_status==='stale'?' critical':''}"></span><div>${agentTicketLink(central,s)}<span class="meta">Status ${esc(s.current_ticket_status||s.status||a.pool_status||'Not observed')}</span><span class="meta">${esc(s.project||`${s.role||managed?.role||'worker'} · ${s.board_id}`)}</span></div><span class="meta work-timing">${esc(agentRosterTiming(a,s))}</span></div>`).join(''):`<div class="work-row empty-work"><span class="severity${a.pool_status==='stale'?' critical':''}"></span><div><b>Current ticket</b><span class="meta">None recorded</span></div><span class="meta work-timing">${esc(agentRosterTiming(a,{}))}</span></div>`}${managed?managedControls(central,managed,false):'<span class="meta">Live pool seat · not locally managed</span>'}</article>`}
