function inactiveAgentDrawer(){const rows=[];for(const [central,d] of Object.entries(fleetData))for(const a of d.inactive_agents||[])rows.push({central,agent:a});if(!rows.length)return'';return `<details id="inactive-agent-drawer" class="card pool"><summary>Retired / inactive agents · ${rows.length}</summary><div class="table-scroll"><table><thead><tr><th>Name</th><th>Lifecycle</th><th>Board</th><th>Stable identity</th><th>Last seen</th></tr></thead><tbody>${rows.sort((x,y)=>x.agent.agent_name.localeCompare(y.agent.agent_name)||agentIdentity(x.agent).localeCompare(agentIdentity(y.agent))).map(x=>`<tr><td><b>${esc(x.agent.agent_name)}</b><div class="meta">${esc(x.central)}</div></td><td><span class="status">${esc(x.agent.lifecycle_status||'inactive')}</span></td><td>${esc(x.agent.board_id||'—')}</td><td class="id">${esc(agentIdentityLabel(x.agent))}</td><td>${esc(relativeAge(x.agent.last_seen))}</td></tr>`).join('')}</tbody></table></div></details>`}
function agentPoolScope(){const covered=[],excluded=[],unreadable=[];for(const [central,d] of Object.entries(fleetData)){const scope=d.pool_scope||{};for(const board of scope.covered_boards||[])covered.push({central,board});for(const row of scope.excluded_boards||[])excluded.push({central,...row});for(const board of scope.configured_but_unreadable||[])unreadable.push({central,board})}const state=excluded.length?'error':covered.length?'ready':'empty';return`<details class="card pool agent-pool-scope" data-pursers-panel="agents" data-pursers-state="${state}"><summary><b>Pool scope</b> · ${covered.length} covered</summary><p class="muted">Boards covered: ${covered.length?covered.map(x=>`<span class="pill" data-pursers-board="${esc(x.board)}" data-pursers-status="ready">${esc(x.central)} · ${esc(x.board)}</span>`).join(' '):'none'}</p>${excluded.length?`<p class="warning">Readable but excluded: ${excluded.map(x=>`<span data-pursers-board="${esc(x.board_id)}" data-pursers-status="error">${esc(x.central)} · ${esc(x.board_id)} (${esc(x.reason||'unavailable')})</span>`).join(', ')}</p>`:''}${unreadable.length?`<p class="meta">Configured but not readable: ${unreadable.map(x=>`${esc(x.central)} · ${esc(x.board)}`).join(', ')}</p>`:''}</details>`}
